private const val COLOR_MODE_KEY = "debuggingamie:colorMode"

@InitSilk
fun initColorMode(ctx: InitSilkContext) {
    ctx.config.initialColorMode = ColorMode.loadFromLocalStorage(COLOR_MODE_KEY) ?: ColorMode.systemPreference
}

@InitSilk
fun initSilk(ctx: InitSilkContext) {
    ctx.stylesheet.registerStyleBase("body") {
        Modifier.fontFamily("JakartaSans", "sans-serif")
    }
}

@InitSilk
fun initStyles(ctx: InitSilkContext) {
    ctx.stylesheet.apply {
        registerStyleBase("body") { Modifier.scrollBehavior(ScrollBehavior.Smooth) }
        registerStyle(".reveal-on-scroll") {
            cssRule("") {
                Modifier
                    .opacity(0)
                    .transform { translateY(40.px) }
                    .styleModifier {
                        property("transition", "opacity 0.8s cubic-bezier(0.16, 1, 0.3, 1), transform 0.8s cubic-bezier(0.16, 1, 0.3, 1)")
                    }
            }
        }
        registerStyle(".reveal-visible") {
            cssRule("") {
                Modifier
                    .opacity(1)
                    .transform { translateY(0.px) }
            }
        }
    }
}

@App
@Composable
fun AppEntry(content: @Composable () -> Unit) {
    SilkApp {
        val colorMode = ColorMode.current
        LaunchedEffect(colorMode) {
            colorMode.saveToLocalStorage(COLOR_MODE_KEY)
        }
        Surface(SmoothColorStyle.toModifier().minHeight(100.vh)) {
            content()
        }
    }
}

// Token definition and Syntax Highlighter for Kotlin
data class CodeToken(val text: String, val color: Color)

private val KEYWORDS = setOf(
    "import", "package", "val", "var", "fun", "class", "object", "interface",
    "enum", "when", "if", "else", "for", "while", "return", "by", "is", "as",
    "in", "null", "true", "false", "this", "super", "try", "catch", "throw"
)

private val TYPES = setOf(
    "AmieEngine", "AmiePipeline", "Precision", "Provider", "CUDA", "FP16",
    "String", "List", "Int", "Boolean", "Unit", "Long", "Double", "Float"
)

private val KEYWORD_COLOR = Color.rgb(204, 120, 50)      // IntelliJ Orange/Brown #CC7832
private val TYPE_COLOR = Color.rgb(78, 201, 176)         // Teal/Cyan #4EC9B0
private val FUNCTION_COLOR = Color.rgb(255, 198, 109)    // IntelliJ Gold #FFC66D
private val STRING_COLOR = Color.rgb(106, 135, 89)       // IntelliJ String Green #6A8759
private val NUMBER_COLOR = Color.rgb(104, 151, 187)      // Light Blue #6897BB
private val COMMENT_COLOR = Color.rgb(128, 128, 128)     // Gray #808080
private val DEFAULT_COLOR = Color.rgb(169, 183, 198)     // Soft White #A9B7C6
private val PUNCT_COLOR = Color.rgb(204, 204, 204)       // Light Gray #CCCCCC

fun tokenizeKotlinLine(line: String): List<CodeToken> {
    val trimmed = line.trimStart()
    if (trimmed.startsWith("//")) {
        val leadingSpaces = line.takeWhile { it == ' ' }
        val tokens = mutableListOf<CodeToken>()
        if (leadingSpaces.isNotEmpty()) {
            tokens.add(CodeToken(leadingSpaces, DEFAULT_COLOR))
        }
        tokens.add(CodeToken(trimmed, COMMENT_COLOR))
        return tokens
    }

    val tokens = mutableListOf<CodeToken>()
    var i = 0
    val n = line.length

    while (i < n) {
        val ch = line[i]

        // Whitespace
        if (ch == ' ' || ch == '\t') {
            val sb = StringBuilder()
            while (i < n && (line[i] == ' ' || line[i] == '\t')) {
                sb.append(line[i])
                i++
            }
            tokens.add(CodeToken(sb.toString(), DEFAULT_COLOR))
            continue
        }

        // String literal
        if (ch == '"') {
            val sb = StringBuilder()
            sb.append(ch)
            i++
            while (i < n) {
                val c = line[i]
                sb.append(c)
                i++
                if (c == '"' && (i < 2 || line[i - 2] != '\\')) {
                    break
                }
            }
            tokens.add(CodeToken(sb.toString(), STRING_COLOR))
            continue
        }

        // Number
        if (ch.isDigit()) {
            val sb = StringBuilder()
            while (i < n && (line[i].isDigit() || line[i] == '.')) {
                sb.append(line[i])
                i++
            }
            tokens.add(CodeToken(sb.toString(), NUMBER_COLOR))
            continue
        }

        // Identifiers / Keywords / Types / Functions
        if (ch.isLetter() || ch == '_') {
            val sb = StringBuilder()
            while (i < n && (line[i].isLetterOrDigit() || line[i] == '_')) {
                sb.append(line[i])
                i++
            }
            val word = sb.toString()

            var lookAheadIndex = i
            while (lookAheadIndex < n && line[lookAheadIndex] == ' ') {
                lookAheadIndex++
            }
            val isFunction = lookAheadIndex < n && line[lookAheadIndex] == '('

            val color = when {
                word in KEYWORDS -> KEYWORD_COLOR
                word in TYPES || word.first().isUpperCase() -> TYPE_COLOR
                isFunction -> FUNCTION_COLOR
                else -> DEFAULT_COLOR
            }
            tokens.add(CodeToken(word, color))
            continue
        }

        // Arrow operator ->
        if (ch == '-' && i + 1 < n && line[i + 1] == '>') {
            tokens.add(CodeToken("->", KEYWORD_COLOR))
            i += 2
            continue
        }

        // Other punctuation / symbols
        tokens.add(CodeToken(ch.toString(), PUNCT_COLOR))
        i++
    }

    return tokens
}

enum class CodeSnippetType(val title: String, val lines: List<String>) {
    QUICK_START(
        "Quick Start",
        listOf(
            "import org.example.amie.AmieEngine",
            "",
            "// Initialize the AMIE Runtime Engine",
            "val amie = AmieEngine.init()",
            "val constraints = listOf(\"greetings\", \"qa_model\")",
            "amie.argmax(constraints) { result ->",
            "    println(\"Pipeline Output: \${result.text}\")",
            "}"
        )
    ),
    PIPELINE(
        "Pipeline Config",
        listOf(
            "import org.example.amie.AmiePipeline",
            "import org.example.amie.Precision",
            "import org.example.amie.Provider",
            "",
            "val pipeline = AmiePipeline.builder()",
            "    .addModel(\"bert_base.onnx\", precision = Precision.FP16)",
            "    .setExecutionProvider(Provider.CUDA)",
            "    .build()",
            "",
            "pipeline.executeAsync(inputData)"
        )
    ),
    STREAMING(
        "Real-Time Stream",
        listOf(
            "// Create a streaming LLM inference session",
            "val stream = amie.createStreamSession(\"llm_onnx\")",
            "stream.onToken { token ->",
            "    ui.appendToken(token)",
            "}",
            "stream.start(prompt = \"Explain ONNX optimization\")"
        )
    )
}

