@Page
@Composable
fun HomePage() {
    var activeNav by remember { mutableStateOf("Home") }

    // Scroll reveal observer
    LaunchedEffect(activeNav) {
        delay(100)
        try {
            js("""
                const observer = new IntersectionObserver((entries) => {
                    entries.forEach((entry) => {
                        if (entry.isIntersecting) {
                            entry.target.classList.add('reveal-visible');
                        }
                    });
                }, { threshold: 0.1 });

                document.querySelectorAll('.reveal-on-scroll').forEach((el) => {
                    observer.observe(el);
                });
            """)
        } catch (e: Throwable) {
            // fallback
        }
    }

    Column(
        modifier = Modifier
            .fillMaxSize()
            .minHeight(100.vh)
            .backgroundColor(Colors.Black),
        verticalArrangement = Arrangement.SpaceBetween,
        horizontalAlignment = Alignment.CenterHorizontally
    ) {
        // Sticky Fixed Header Container
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .position(Position.Sticky)
                .top(0.px)
                .zIndex(100)
                .backgroundColor(Colors.Black)
        ) {
            DevelopmentBanner()
            HeaderSection(
                activeNav = activeNav,
                onNavSelected = { nav ->
                    activeNav = nav
                    val targetId = when (nav) {
                        "Home" -> "home"
                        "Documentation" -> "documentation"
                        "Examples" -> "examples"
                        else -> "home"
                    }
                    window.document.getElementById(targetId)?.scrollIntoView(
                        js("{ behavior: 'smooth', block: 'start' }")
                    )
                }
            )
        }

        // Dynamic Main Content Area with Scroll Reveal & Gradient
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .maxWidth(1000.px)
                .padding(top = 30.px, bottom = 60.px, leftRight = 20.px)
                .gap(36.px)
                .styleModifier {
                    property("background", "radial-gradient(circle at 50% 25%, rgba(60, 90, 180, 0.12) 0%, rgba(0, 0, 0, 0) 70%)")
                },
            horizontalAlignment = Alignment.CenterHorizontally
        ) {
            when (activeNav) {
                "Home" -> {
                    Box(
                        modifier = Modifier
                            .id("home")
                            .fillMaxWidth()
                            .classNames("reveal-on-scroll"),
                        contentAlignment = Alignment.Center
                    ) {
                        BriefDescription()
                    }
                    Box(
                        modifier = Modifier
                            .id("download")
                            .fillMaxWidth()
                            .classNames("reveal-on-scroll"),
                        contentAlignment = Alignment.Center
                    ) {
                        DownloadBox()
                    }
                    Box(
                        modifier = Modifier
                            .id("examples")
                            .fillMaxWidth()
                            .classNames("reveal-on-scroll"),
                        contentAlignment = Alignment.Center
                    ) {
                        BriefExample()
                    }
                }
                "Documentation" -> {
                    Box(
                        modifier = Modifier
                            .id("documentation")
                            .fillMaxWidth()
                            .classNames("reveal-on-scroll"),
                        contentAlignment = Alignment.Center
                    ) {
                        UnderConstructionSection(title = "Documentation", onBackToHome = { activeNav = "Home" })
                    }
                }
                "Examples" -> {
                    Box(
                        modifier = Modifier
                            .id("examples")
                            .fillMaxWidth()
                            .classNames("reveal-on-scroll"),
                        contentAlignment = Alignment.Center
                    ) {
                        UnderConstructionSection(title = "Examples", onBackToHome = { activeNav = "Home" })
                    }
                }
            }
        }

        // Footer
        FooterSection()
    }
}

