@Composable
fun BriefExample() {
    var activeSnippet by remember { mutableStateOf(CodeSnippetType.QUICK_START) }
    var isSnippetCopied by remember { mutableStateOf(false) }
    val scope = rememberCoroutineScope()

    Column(
        modifier = Modifier
            .width(100.percent)
            .maxWidth(680.px)
            .backgroundColor(Color.rgb(18, 18, 18))
            .border(width = 1.px, style = LineStyle.Solid, color = Color.rgb(50, 50, 60))
            .borderRadius(16.px)
            .padding(all = 28.px)
            .gap(20.px)
            .styleModifier {
                property("background", "radial-gradient(ellipse at top, rgba(35, 45, 60, 0.8) 0%, rgba(18, 18, 18, 1) 100%)")
                property("box-shadow", "0 10px 40px -10px rgba(70, 130, 240, 0.2), 0 0 30px 0 rgba(0, 0, 0, 0.5)")
            }
    ) {
        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.SpaceBetween,
            verticalAlignment = Alignment.CenterVertically
        ) {
            H3(
                attrs = Modifier
                    .color(Colors.White)
                    .fontSize(18.px)
                    .fontWeight(FontWeight.Bold)
                    .margin(all = 0.px)
                    .fontFamily("JakartaSans", "sans-serif")
                    .toAttrs()
            ) {
                Text("Code Example")
            }

            Row(modifier = Modifier.gap(6.px)) {
                CodeSnippetType.entries.forEach { snippet ->
                    val isSelected = activeSnippet == snippet
                    Button(
                        attrs = Modifier
                            .backgroundColor(if (isSelected) Colors.White else Color.rgb(30, 30, 30))
                            .color(if (isSelected) Colors.Black else Colors.LightGray)
                            .border(width = 1.px, style = LineStyle.Solid, color = if (isSelected) Colors.White else Colors.Gray)
                            .fontFamily("JakartaSans", "sans-serif")
                            .fontSize(12.px)
                            .borderRadius(6.px)
                            .padding(topBottom = 4.px, leftRight = 10.px)
                            .cursor(Cursor.Pointer)
                            .onClick {
                                activeSnippet = snippet
                                isSnippetCopied = false
                            }
                            .toAttrs()
                    ) {
                        Text(snippet.title)
                    }
                }
            }
        }

        // Code block with Kotlin Syntax Highlighting
        Column(
            modifier = Modifier
                .fillMaxWidth()
                .backgroundColor(Color.rgb(10, 10, 10))
                .padding(all = 16.px)
                .borderRadius(8.px)
                .border(width = 1.px, style = LineStyle.Solid, color = Color.rgb(40, 40, 40))
                .fontFamily("monospace")
                .fontSize(13.px)
        ) {
            activeSnippet.lines.forEachIndexed { index, line ->
                Row(
                    modifier = Modifier.margin(bottom = 4.px),
                    verticalAlignment = Alignment.CenterVertically
                ) {
                    Span(
                        attrs = Modifier
                            .color(Color.rgb(90, 90, 90))
                            .width(28.px)
                            .userSelect(UserSelect.None)
                            .toAttrs()
                    ) {
                        Text("${index + 1}")
                    }
                    Span(attrs = Modifier.margin(left = 8.px).toAttrs()) {
                        val tokens = tokenizeKotlinLine(line)
                        tokens.forEach { token ->
                            Span(
                                attrs = Modifier
                                    .color(token.color)
                                    .toAttrs()
                            ) {
                                Text(token.text)
                            }
                        }
                    }
                }
            }
        }

        Row(
            modifier = Modifier.fillMaxWidth(),
            horizontalArrangement = Arrangement.End,
            verticalAlignment = Alignment.CenterVertically
        ) {
            Button(
                attrs = Modifier
                    .backgroundColor(if (isSnippetCopied) Colors.Green else Colors.White)
                    .color(if (isSnippetCopied) Colors.White else Colors.Black)
                    .fontFamily("JakartaSans", "sans-serif")
                    .fontWeight(FontWeight.Bold)
                    .fontSize(13.px)
                    .padding(topBottom = 6.px, leftRight = 14.px)
                    .borderRadius(6.px)
                    .border(width = 0.px, style = LineStyle.None, color = Colors.Transparent)
                    .cursor(Cursor.Pointer)
                    .onClick {
                        val fullCode = activeSnippet.lines.joinToString("\n")
                        window.navigator.clipboard.writeText(fullCode)
                        isSnippetCopied = true
                        scope.launch {
                            delay(2.seconds)
                            isSnippetCopied = false
                        }
                    }
                    .toAttrs()
            ) {
                Row(
                    verticalAlignment = Alignment.CenterVertically,
                    modifier = Modifier.gap(6.px)
                ) {
                    if (isSnippetCopied) {
                        FaCheck()
                        Text("Copied Snippet")
                    } else {
                        FaCopy()
                        Text("Copy Snippet")
                    }
                }
            }
        }
    }
}

